INSERT INTO `ai_class_facts` (`id`, `fact_text`, `created_at`) VALUES
(1, 'Tempering cocoa butter requires precisely forming Type V crystals for that satisfying snap and glossy finish.', '2026-07-07 21:05:43'),
(2, 'Under-roasting cacao beans leads to high acidity and lack of deep chocolate flavor notes in the final bar.', '2026-07-07 21:05:43'),
(3, 'The conching process reduces volatile acids (like acetic acid) and coats solid particles with cocoa butter for a smooth mouthfeel.', '2026-07-07 21:05:43'),
(4, 'Adding lecithin (an emulsifier) reduces chocolate viscosity significantly, making it easier to mould or coat.', '2026-07-07 21:05:43'),
(5, 'Roasting temperature profiles are varied: high-temperature short-time (HTST) for floral profiles, low-temperature long-time (LTLT) for earthy profiles.', '2026-07-07 21:05:43');
INSERT INTO `ai_ingredient_spotlights` (`id`, `ingredient_name`, `tag`, `short_desc`, `detailed_notes`, `flavor_notes`, `origin_region`, `modal_key`, `created_at`) VALUES
(94, 'Lecithin', '🌱 INGREDIENT SPOTLIGHT', 'A natural emulsifier, usually from soybeans. It helps cocoa particles mix smoothly with cocoa butter, improving texture and flow.', 'Lecithin reduces viscosity, allowing less cocoa butter to be used while keeping chocolate smooth and well blended.', 'emulsifier, mixing, texture', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-10-30 14:28:17'),
(95, 'Cocoa Butter', '🌱 INGREDIENT SPOTLIGHT', 'The natural fat from cocoa beans. It gives chocolate smooth texture, clean melt and snap. During tempering, it forms stable crystals that create the firm snap, while its low melting point lets it melt smoothly.', 'Cocoa butter melts near body temperature and forms stable Beta-V crystals during tempering, giving chocolate its characteristic snap.', 'natural fat, texture, tempering', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-10-31 00:59:29'),
(96, 'Cocoa Powder', '🌱 INGREDIENT SPOTLIGHT', 'Cocoa powder is finely ground cocoa solids and fat from roasted beans. It adds intense chocolate flavor and color while reducing moisture in chocolate formulations.', 'Cocoa powder is made by pressing most of the cocoa butter out of roasted beans, leaving a dry cake that is ground into powder. This dry form adds strong chocolate flavor and color while keeping recipes less greasy.', 'ground cocoa solids, flavor, chocolate making', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-01 15:37:22'),
(97, 'Cocoa Nibs', '🌱 INGREDIENT SPOTLIGHT', 'Cocoa nibs are the broken pieces of roasted cocoa beans. They add a rich, earthy crunch and contribute natural cocoa flavor, giving chocolate its characteristic bite and complexity.', 'Cocoa nibs retain the bean’s natural cocoa solids, providing direct flavor and a crisp texture that enhances chocolate’s overall taste profile.', 'cocoa pieces, flavor, mixing', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-02 01:20:42'),
(98, 'Lecithin', '🌱 INGREDIENT SPOTLIGHT', 'Lecithin is an emulsifier derived from soy or sunflower that helps cocoa particles stay evenly dispersed in chocolate, preventing graininess and ensuring a smooth, glossy finish.', 'When added in small amounts, lecithin reduces surface tension between cocoa solids and fat, allowing the mixture to flow uniformly and stay stable during storage.', 'soy emulsifier, even dispersion, mixing', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-02 09:05:47'),
(99, 'Lecithin', '🌱 INGREDIENT SPOTLIGHT', 'Lecithin is a natural emulsifier, meaning it helps cocoa butter and cocoa solids mix evenly. It improves chocolate’s flow during production and prevents separation without changing flavor.', 'Lecithin lowers the thickness of melted chocolate so it flows more easily during molding and coating.', 'natural emulsifier, blending, flow', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-02 16:49:45'),
(100, 'Cocoa Powder', '🌱 INGREDIENT SPOTLIGHT', 'Cocoa powder is finely ground cocoa solids from roasted beans, offering deep chocolate flavor and acting as a thickening agent in chocolate recipes which also influences texture and color.', 'Cocoa powder is made by grinding the cocoa solids left after cocoa butter is removed, preserving the bean’s flavor compounds and pigments. It is commonly used to flavor and thicken chocolate mixtures and to provide color.', 'ground cocoa solids, flavor, chocolate making', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-03 03:07:22'),
(101, 'Cocoa Powder', '🌱 INGREDIENT SPOTLIGHT', 'Cocoa powder is finely ground cocoa solids. It adds rich chocolate flavor, helps thicken mixtures, and provides consistent cocoa intensity for baking everyday drinking beverages.', 'Cocoa powder contains cocoa solids and some cocoa butter. It dissolves easily in liquids, giving a uniform chocolate taste without affecting melt properties.', 'ground solids, flavor, baking drinks', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-03 10:36:40'),
(102, 'Cocoa Nibs', '🌱 INGREDIENT SPOTLIGHT', 'Crumbled pieces of roasted cocoa bean. They add bitter cocoa flavor and texture to chocolate, providing a chewy bite and natural cocoa taste for richer flavor.', 'Cocoa nibs are the broken bits of roasted cocoa beans after the shell is removed. They contribute cocoa flavor and a slight crunch, making them useful in cookies, granolas, and chocolate bars.', 'cocoa pieces, flavor, baking', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-03 18:52:12'),
(103, 'Cocoa Powder', '🌱 INGREDIENT SPOTLIGHT', 'Cocoa powder is finely ground cocoa solids with most of the cocoa butter removed. It adds rich chocolate flavor and color while providing natural acidity for balanced taste.', 'When mixed into chocolate, cocoa powder contributes solids that give structure and flavor. Its natural acidity helps balance sweetness and improves texture.', 'ground cocoa solids, flavor, mixing', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-04 18:51:42'),
(104, 'Cocoa Nibs', '🌱 INGREDIENT SPOTLIGHT', 'Cracked cocoa beans rich in cocoa solids and cocoa butter. It adds a strong, bitter chocolate flavor and is often used as decoration or baking.', 'Cocoa nibs are crushed cocoa beans. They contain cocoa solids and cocoa butter, so they add strong chocolate flavor.', 'cocoa bean pieces, chocolate flavor, baking', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-06 12:20:38'),
(105, 'Cocoa Butter', '🌱 INGREDIENT SPOTLIGHT', 'The natural fat extracted from cocoa beans during processing. It gives chocolate its signature smooth texture, clean melt, and pleasant snap when biting into a piece.', 'Cocoa butter melts sharply at human body temperature (around 34-38°C) and crystallizes into stable Beta-V crystals during tempering to ensure proper snap and gloss.', 'natural fat, texture, tempering', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-07 18:08:08'),
(106, 'Cocoa Nibs', '🌱 INGREDIENT SPOTLIGHT', 'Cocoa nibs are chopped pieces of roasted cocoa bean. They add crunchy texture and deep cocoa flavor to desserts and baked goods. And they provide natural cocoa aroma and subtle bitterness.', 'Cocoa nibs retain the bean\'s fibrous structure, giving a slight bite. They are often used in trail mixes, cookies, and cakes for added cocoa presence.', 'chopped cocoa bean, texture & flavor, desserts', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-07 18:08:09'),
(107, 'Cocoa Butter', '🌱 INGREDIENT SPOTLIGHT', 'Cocoa butter is the natural fat left in dried cocoa beans. It gives chocolate its smooth melt, clean snap, and glossy finish during proper tempering.', 'During tempering, cocoa butter melts sharply at body heat and then forms stable crystals. These crystals give chocolate a glossy shine and firm snap.', 'natural fat, texture, tempering', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-13 08:53:14'),
(108, 'Lecithin', '🌱 INGREDIENT SPOTLIGHT', 'Lecithin is a natural emulsifier, usually made from soy or sunflower. In chocolate, it reduces thickness, helping the mixture flow smoothly so less cocoa butter is needed.', 'Lecithin coats solid particles like sugar, reducing friction between them. This lowers the chocolate\'s thickness, so makers can use less cocoa butter while keeping it easy to work with.', 'natural emulsifier, reduces thickness, flow', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-13 15:59:22'),
(109, 'Lecithin', '🌱 INGREDIENT SPOTLIGHT', 'Lecithin is a natural emulsifier, a substance that helps ingredients mix smoothly. In chocolate, it reduces thickness, so makers can use less cocoa butter while keeping chocolate easy to pour and mold.', 'Lecithin is commonly added in small amounts to lower chocolate’s thickness, helping it flow during molding and coating.', 'natural emulsifier, reduces thickness, flow and molding', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-14 01:01:10'),
(110, 'Cocoa Butter', '🌱 INGREDIENT SPOTLIGHT', 'Cocoa butter is the natural fat from cocoa beans, providing smooth texture, proper snap, and stable crystallization during tempering, which gives chocolate its characteristic snap and melt.', 'Cocoa butter melts near body temperature and forms stable Beta-V crystals when tempered, giving chocolate its snap.', 'natural fat, texture, tempering', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-14 14:58:39'),
(111, 'Cocoa Powder', '🌱 INGREDIENT SPOTLIGHT', 'Cocoa powder is finely ground cocoa solids with a touch of cocoa butter. It delivers deep chocolate flavor and rich color while keeping the chocolate light and smooth.', 'Cocoa powder is made by pressing out most of the cocoa butter, leaving dry cocoa solids that are then ground into a fine powder. This concentrated form adds strong chocolate taste and color without adding extra fat.', 'ground cocoa solids, flavor and color, chocolate making', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-15 08:00:18'),
(112, 'Cocoa Nibs', '🌱 INGREDIENT SPOTLIGHT', 'Cocoa nibs are the broken pieces of roasted cocoa beans. They add rich, earthy flavor and a pleasant crunch to chocolate, contributing to both taste and texture.', 'Cocoa nibs come from de-shelled cocoa beans after roasting. They retain the cocoa solids, providing natural flavor and a slight bite in final products.', 'chopped beans, flavor & texture, confectionery', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-15 19:47:50'),
(113, 'Lecithin', '🌱 INGREDIENT SPOTLIGHT', 'Lecithin is an emulsifier often derived from soy or sunflower. In chocolate, it helps cocoa particles and sugar mix smoothly with cocoa butter, reducing viscosity so melted chocolate flows more easily.', 'Lecithin coats particles and lowers friction between them, so manufacturers can reduce cocoa butter while keeping chocolate fluid. It is commonly used at low levels.', 'emulsifier, reduces viscosity, chocolate flow', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-18 00:46:55'),
(114, 'Lecithin', '🌱 INGREDIENT SPOTLIGHT', 'A natural emulsifier usually made from soybeans or sunflower seeds. It helps cocoa butter and cocoa solids mix evenly, making chocolate flow better during processing.', 'Lecithin coats solid particles and reduces friction between them, lowering chocolate’s viscosity and improving flow without requiring extra cocoa butter.', 'emulsifier, improve flow, processing', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-18 14:59:50'),
(115, 'Cocoa Butter', '🌱 INGREDIENT SPOTLIGHT', 'Cocoa butter is the natural fat from cocoa beans. It gives chocolate a smooth melt and firm snap, and helps keep cocoa solids and sugar evenly spread.', 'Cocoa butter melts near human body temperature and forms stable crystals when chocolate is tempered. This helps chocolate feel smooth and set with a good snap.', 'natural fat, texture, tempering', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-19 04:08:19'),
(116, 'Lecithin', '🌱 INGREDIENT SPOTLIGHT', 'Soy lecithin acts as an emulsifier, evenly dispersing cocoa solids through cocoa butter to prevent separation and create a consistent, smooth chocolate texture during manufacturing.', 'Lecithin molecules have a dual affinity for fat and water, linking cocoa butter and particulate matter. This reduces friction and viscosity, enabling efficient processing without compromising snap or sheen.', 'emulsifier, emulsification, texture', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-19 04:08:27'),
(117, 'Cocoa Nibs', '🌱 INGREDIENT SPOTLIGHT', 'Crushed, roasted cocoa beans with shells removed. They deliver the essential chocolate flavor and gritty texture before grinding into smooth cocoa mass for chocolate making.', 'Nibs are the pure, edible kernel of the cocoa bean. Grinding them releases cocoa butter and creates cocoa mass, the base of all chocolate.', 'crushed beans, flavor source, grinding', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-20 08:29:50'),
(118, 'Lecithin', '🌱 INGREDIENT SPOTLIGHT', 'Lecithin is a natural emulsifier often derived from soy or sunflower. In chocolate, it helps cocoa particles and sugar mix smoothly with cocoa butter, reducing viscosity and improving flow.', 'Lecithin reduces the amount of cocoa butter needed to make chocolate flow well during processing. It is commonly used at low levels and is not a flavor ingredient.', 'emulsifier, flow, viscosity control', 'Level 1 — Chocolate Fundamentals', 'ingredient-spotlight', '2026-11-21 08:32:50');
