INSERT INTO `faqs` (`id`, `question`, `answer`, `category`, `display_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'What is RT Chocos?', 'RT Chocos is India\'s first chocolate blogging website and bean-to-bar learning academy. Founded by Aarti Saluja Sahni, we teach the science of cocoa processing, formulation, and tempering while offering professional workshops and premium craft chocolate tools.', 'general', 1, 1, '2026-07-13 21:26:01', '2026-07-13 21:26:01'),
(2, 'What does bean-to-bar mean?', 'Bean-to-bar refers to the process where a chocolate maker controls every step of production, starting from raw cacao beans to the finished chocolate bar. This includes sourcing, roasting, cracking, winnowing, grinding, conching, aging, tempering, and molding.', 'general', 2, 1, '2026-07-13 21:26:01', '2026-07-13 21:26:01'),
(3, 'Who is Aarti Saluja Sahni?', 'Aarti Saluja Sahni is the founder of RT Chocos, India\'s first chocolate educator and consulting expert. With 13+ years of experience in bean-to-bar chocolate making, recipe formulation, and brand consulting, she has trained more than 2,000 students across India.', 'general', 3, 1, '2026-07-13 21:26:01', '2026-11-02 07:24:45'),
(4, 'What workshops does RT Chocos offer?', 'We offer professional bean-to-bar workshops, tempering science masterclasses, and chocolate making courses in Mumbai and online. These sessions cover cacao selection, roasting profiles, tempering chemistry, and flavor formulation.', 'workshops', 1, 1, '2026-07-13 21:26:01', '2026-07-13 21:26:01'),
(5, 'Do I get a certificate after completing a workshop?', 'Yes, participants receive an official Certificate of Completion from RT Chocos Chocolate Academy. This certificate recognizes your training in professional bean-to-bar craft chocolate making and chocolate science.', 'workshops', 2, 1, '2026-07-13 21:26:01', '2026-07-13 21:26:01'),
(6, 'Can I attend workshops online?', 'Yes, we conduct live online interactive workshops via Zoom. We ship a curated ingredient and toolkit box to your address before the session so you can practice bean-to-bar and tempering science hands-on along with Aarti.', 'workshops', 3, 1, '2026-07-13 21:26:01', '2026-07-13 21:26:01'),
(7, 'What products does RT Chocos sell?', 'We sell premium artisan bean-to-bar dark chocolates, roasted single-origin cacao nibs, home chocolate making starter kits, and professional recipe formulation guides designed by chocolate consultant Aarti Saluja Sahni.', 'shop', 1, 1, '2026-07-13 21:26:01', '2026-07-13 21:26:01'),
(8, 'Are RT Chocos products vegetarian?', 'Yes, all products in our online shop are 100% vegetarian. Our dark chocolate bars are also vegan, dairy-free, gluten-free, and made using only organic cane sugar and pure single-origin Indian cocoa beans.', 'shop', 2, 1, '2026-07-13 21:26:02', '2026-07-13 21:26:02'),
(9, 'Can I return or exchange products?', 'Due to the perishable nature of artisanal chocolate, we do not accept returns or exchanges on food items once shipped. For tools, starter kits, or damaged items, contact hello@rtchocos.com within 7 days of delivery for a replacement.', 'shop', 3, 1, '2026-07-13 21:26:02', '2026-07-13 21:26:02'),
(10, 'Do you ship across India?', 'Yes, we ship our chocolates, kits, and tools to all major cities and towns across India. We partner with express temperature-controlled courier networks to ensure your chocolate products arrive safely without melting.', 'shipping', 1, 1, '2026-07-13 21:26:02', '2026-07-13 21:26:02'),
(11, 'How are chocolates packed for shipping?', 'Every chocolate order is shipped in food-grade insulated boxes containing reusable ice gel packs. This protective packaging keeps the temperature cool throughout transit, maintaining the chocolate\'s tempered state.', 'shipping', 2, 1, '2026-07-13 21:26:02', '2026-07-13 21:26:02'),
(12, 'Is there free shipping?', 'We offer free standard shipping across India on all orders of ₹999 and above. For orders under ₹999, a flat shipping fee of ₹99 is applied at checkout to cover temperature-controlled packaging costs.', 'shipping', 3, 1, '2026-07-13 21:26:02', '2026-07-13 21:26:02'),
(13, 'How is a course different from a workshop?', 'Workshops are hands-on, single-session masterclasses focusing on a specific skill (e.g. tempering). Professional courses are comprehensive, multi-week programs covering everything from raw cacao chemistry to scale business setup.', 'courses', 1, 1, '2026-07-13 21:26:02', '2026-07-13 21:26:02'),
(14, 'What are the prerequisites for joining a course?', 'There are no prerequisites! Our bean-to-bar chocolate making courses are designed to take you from a complete beginner to a confident craft chocolate maker. No culinary background is required to enroll.', 'courses', 2, 1, '2026-07-13 21:26:02', '2026-07-13 21:26:02'),
(15, 'How much do courses cost?', 'Course fees vary depending on the depth, duration, and format (online vs. in-person). Standard online workshops start from ₹4,999, while professional certification programs range between ₹14,999 and ₹29,999.', 'courses', 3, 1, '2026-07-13 21:26:02', '2026-07-13 21:26:02');
INSERT INTO `lab_experiments` (`id`, `title`, `slug`, `category`, `status_badge`, `status_color`, `image_path`, `description`, `tags`, `hypothesis`, `methodology`, `findings`, `next_steps`, `full_content`, `is_featured`, `sort_order`, `is_active`, `created_at`, `updated_at`, `origin`, `polymorph`, `particle_size`, `conching`, `water_activity`, `batch_ref`) VALUES
(1, 'CBE × Bean-to-Bar', 'cbe-bean-to-bar', 'formulation-lab', 'IN PROGRESS', 'green', 'assets/images/lab-cbe.jpg', 'Can cocoa butter equivalents deliver great texture, snap and flavour in high-cocoa chocolate?', 'FAT SYSTEMS | FORMULATION', 'Non-lauric cocoa butter equivalents (CBE) blended at 5% will maintain Beta-V crystal stability while boosting heat tolerance in tropical ambient temperatures without compromising snap.', 'Formulated 70% single-origin Kerala cacao with 5% CBE fat replacement. Monitored temper curves on Selmi tempering unit, differential scanning calorimetry (DSC), and snap test after 30 days.', 'Temper curves showed sharp Beta-V peaks. Melting point increased by +1.8°C with zero noticeable waxiness on the palate. Flavour profile remained authentic.', 'Conduct 60-day fat bloom cycling tests at 28°C-32°C.', '<h2>The Research Objective</h2>\r\n<p>In tropical climates like Southern India, ambient kitchen temperatures routinely exceed 30°C. Managing <em>fat bloom</em> and maintaining sharp crystal snap has historically forced mass-market confectionery producers toward hydrogenated palm fats and compound coatings—which coat the palate in an unctuous, waxy film and mute delicate cocoa aromatics.</p>\r\n\r\n<blockquote>\r\n<p>\"Our formulation challenge: Introduce clean-label, non-hydrogenated plant lipids (sal, shea, and mango kernel fats) at a strict 5% ratio to support the polymorphic Beta-V crystal matrix under tropical heat stress.\"</p>\r\n</blockquote>\r\n\r\n<h2>Observations &amp; Sensory Discoveries</h2>\r\n<p>Over a rigorous 60-day testing cycle in our Mumbai and Idukki test kitchens, we tracked crystal formation, snap retention, and sensory palate release across four distinct test batches:</p>\r\n\r\n<ul>\r\n<li><strong>Polymorphic Beta-V Stability:</strong> Differential Scanning Calorimetry (DSC) confirmed sharp Beta-V crystal peaks identical to pure cocoa butter, preventing granular phase separation.</li>\r\n<li><strong>Melting Point Elevation:</strong> The initial melting threshold shifted from <strong>33.8°C to 35.6°C</strong> (+1.8°C increase), dramatically slowing ambient slump without altering mouthfeel.</li>\r\n<li><strong>Aroma &amp; Volatiles:</strong> Headspace aroma analysis revealed zero masking of the bright red-berry and raisin acidity native to our Kerala cacao origin.</li>\r\n<li><strong>Snap Acoustics:</strong> Blind sensory evaluation rated the fracture snap 9.2/10 compared to 9.4/10 on the pure control bar.</li>\r\n</ul>\r\n\r\n<h2>Formulation Trial Metrics</h2>\r\n<table class=\"blog-custom-table blog-table-artisan\">\r\n<thead>\r\n<tr>\r\n  <th>Parameter</th>\r\n  <th>Standard Pure Bar</th>\r\n  <th>5% CBE Trial Batch</th>\r\n  <th>Outcome</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n  <td><strong>Beta-V Crystal Peak</strong></td>\r\n  <td>33.8°C</td>\r\n  <td>35.6°C (+1.8°C)</td>\r\n  <td>Superior heat tolerance</td>\r\n</tr>\r\n<tr>\r\n  <td><strong>Palate Clearance</strong></td>\r\n  <td>12.4 seconds</td>\r\n  <td>13.1 seconds</td>\r\n  <td>Zero waxy residual film</td>\r\n</tr>\r\n<tr>\r\n  <td><strong>Fat Bloom Onset (30°C)</strong></td>\r\n  <td>Day 14</td>\r\n  <td>Day 58+</td>\r\n  <td>4x bloom stability boost</td>\r\n</tr>\r\n<tr>\r\n  <td><strong>Auditory Snap</strong></td>\r\n  <td>Crisp (9.4/10)</td>\r\n  <td>Crisp (9.2/10)</td>\r\n  <td>Authentic temper preserved</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n<h2>Why This Matters to Craft Chocolate</h2>\r\n<p>For artisan chocolate makers across India, summer transport has always been the greatest hurdle between the melanger and the consumer\'s palate. This experiment proves that when fractionated CBE lipids are blended within tight stoichiometric bounds (under 5%), the crystal lattice remains Beta-V dominant, offering chocolate lovers a melt-in-the-mouth sensation that survives the Indian summer.</p>\r\n\r\n<h2>Key Recipe Takeaway &amp; Next Steps</h2>\r\n<p>The 5% CBE formulation has officially passed our kitchen stress trials and is now designated as our approved summer tempering protocol for small-batch single-origin chocolate bars. Next, we will expand this crystal stabilization method to filled bonbon shells and fruit-infused ganaches.</p>', 1, 1, 1, '2026-10-08 15:34:34', '2026-10-30 07:57:16', 'Idukki Estate, Kerala', 'Beta-V Matrix', '< 18.2 µm', '48h Longitudinal', '0.31 Aw', 'RT-EXP-01-CBE'),
(2, 'Freeze-Dried Indian Fruits', 'freeze-dried-indian-fruits', 'ingredient-innovation', 'SENSORY TRIALS', 'amber', 'assets/images/lab-fruits.jpg', 'Can Indian fruits become a premium inclusion? Studying flavour retention, texture and moisture behaviour.', 'INCLUSIONS | SHELF LIFE', 'Freeze-dried Indian heritage fruits (Alphonso mango, pink guava, sun-ripened jamun) retain tart volatile esters better when fat-coated before stone melanging.', 'Pre-treated freeze-dried fruit crunchies with micro-thin cocoa butter barrier spray to inhibit moisture migration from ambient humidity.', 'Crunch retention improved by 340% over 6 weeks. Moisture activity (Aw) remained below 0.35, preventing chocolate sugar-bloom.', 'Sensory panel testing across 30 chocolate enthusiasts for acidity-fat equilibrium.', '<h3>Background</h3>\n<p>India grows some of the world\'s most aromatic fruits, yet most chocolate bars rely on imported freeze-dried strawberries and raspberries. We set out to investigate indigenous cultivars: Ratnagiri Alphonso mango, Allahabad pink guava, and Konkan jamun.</p>\n<h3>Challenges & Solutions</h3>\n<p>The primary enemy of freeze-dried fruit inclusions is moisture hygroscopy: fruit absorbs moisture from the atmosphere and turns chewy or rubbery, releasing free water that causes sugar bloom in chocolate. Applying a 5-micron cocoa butter airbrush coat created an impenetrable barrier while preserving sharp fruit acidity.</p>', 1, 2, 1, '2026-10-08 15:34:34', '2026-10-08 15:34:34', NULL, NULL, NULL, NULL, NULL, NULL),
(3, 'Khandsari Sugar in Dark Chocolate', 'khandsari-sugar-in-dark-chocolate', 'formulation-lab', 'FORMULATION', 'green', 'assets/images/lab-sugar.jpg', 'What changes when traditional Indian sugar meets modern chocolate processing?', 'SUGAR SYSTEMS | TEXTURE', 'Unrefined indigenous Khandsari cane sugar will add warm molasses and caramel complexity to high-percentage dark chocolate without increasing grit.', 'Stone ground Khandsari crystals to particle size < 20 microns over 48 hours in Santha granite melangers. Calibrated conching shear to evaporate moisture.', 'Viscosity remained fluid at 45°C. The natural mineral profile in Khandsari softened the intense tannin bite of South Indian cacao.', 'Standardize drying moisture parameters for seasonal monsoon batches.', '<h3>Heritage Meets Food Science</h3>\n<p>Khandsari is an artisanal, liquid-clarified, unbleached raw cane sugar prepared traditionally without synthetic sulphur. Unlike modern refined white sugar, it carries trace minerals (potassium, iron, magnesium) and subtle malt notes.</p>\n<h3>Particle Micronization</h3>\n<p>Due to residual moisture (0.8% vs 0.04% in refined sugar), conching temperatures were raised incrementally to 58°C with forced dry-air ventilation to vent moisture without seizing the cocoa butter matrix.</p>', 1, 3, 1, '2026-10-08 15:34:34', '2026-10-08 15:34:34', NULL, NULL, NULL, NULL, NULL, NULL),
(4, 'Coconut-Cashew Spread', 'coconut-cashew-spread', 'stability-shelf-life', 'STABILITY STUDY', 'amber', 'assets/images/lab-spread.jpg', 'Can we create a clean label, long shelf-life spread without preservatives?', 'EMULSION | SHELF LIFE', 'Slow-milled cold-pressed roasted cashew and dehydrated coconut butter will create a shelf-stable emulsion without hydrogenated oils or soy lecithin.', 'Conched at 50°C for 24 hours to micro-emulsify cashew natural oils with coconut fat. Packaged under inert nitrogen seal.', 'Oil separation index was < 2% over 90 days. Spreadability maintained at room temperature (22°C - 30°C) with rich mouthfeel.', 'Shelf-life acceleration study under 38°C humidity chamber.', '<h3>Clean Label Formulation</h3>\n<p>Commercial chocolate nut spreads rely on palm oil fractions and chemical stabilizers to stop oil separation. By balancing the fatty acid chain lengths of roasted cashew lipids (primarily oleic acid) with lauric and myristic fats from desiccated coconut, we achieved natural polymorphic lattice immobilization.</p>', 1, 4, 1, '2026-10-08 15:34:34', '2026-10-08 15:34:34', NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `lab_failed_batches` (`id`, `title`, `slug`, `badge_label`, `image_path`, `hypothesis`, `what_happened`, `why_it_happened`, `what_next`, `full_story`, `is_featured`, `sort_order`, `is_active`, `created_at`, `updated_at`, `full_content`) VALUES
(1, 'THE GUAVA EXPERIMENT', 'the-guava-experiment', 'BECAUSE FAILURE IS DATA.', 'assets/images/lab-failed-batch.jpg', 'Freeze-dried guava will create an intense natural fruit note.<div><ul><li>1 hello i am yash vardhan Sharma</li><li>2 hello i am yash vardhan Sharma<br></li><li>3 hello i am yash vardhan Sharma</li><li>4 hello i am yash vardhan Sharma</li></ul></div>', 'Flavour disappeared after incorporation.', 'Possible volatile loss and fat interaction.', 'Test cocoa butter pre-coating.', '<p>During our seasonal fruit inclusion series, we formulated a 65% dark chocolate bar infused with concentrated freeze-dried pink guava chunks. On paper, the high acidity and tropical aroma should have cut right through the dark chocolate astringency. However, upon 48-hour stone melanging, the guava fruit flavor completely vanished on the palate, leaving only a faint sour aftertaste.</p>\r\n<p>After chromatography and moisture checks, we identified that delicate fruit terpene volatiles migrated into the cacao fat matrix, getting encapsulated and suppressed. Furthermore, residual hygroscopic fruit sugars pulled moisture from the air during unsealing.</p>\r\n<p><strong>Lesson Learned:</strong> Hydrophilic fruit compounds must be shielded with an ultra-thin barrier of tempered cocoa butter before introducing them to the stone refiner. Failure transformed our understanding of inclusion kinetics!</p>', 1, 0, 1, '2026-10-08 15:34:34', '2026-10-28 19:56:56', NULL),
(3, 'test', 'test', 'BECAUSE FAILURE IS DATA.', 'assets/images/lab-failed-batch.jpg', '123', '123', '132', '123', '123', 0, 0, 1, '2026-10-28 20:18:15', '2026-10-28 20:20:52', NULL);
INSERT INTO `lab_future_pillars` (`id`, `title`, `description`, `link_url`, `sort_order`, `is_active`, `created_at`) VALUES
(1, 'REGENERATIVE CACAO', 'Agroforestry farming that enriches biodiversity in the Western Ghats.', '#future-ideas', 1, 1, '2026-10-08 15:34:35'),
(2, 'CIRCULAR INGREDIENTS', 'Upcycling cocoa pulp juice and bean husks into prebiotic syrups and infusions.', '#future-ideas', 2, 1, '2026-10-08 15:34:35'),
(3, 'CLIMATE RESILIENCE', 'Heat-tolerant varietal breeding and sustainable shade canopy practices.', '#future-ideas', 3, 1, '2026-10-08 15:34:35'),
(4, 'ALTERNATIVE RAW MATERIALS', 'Cultivating indigenous fat systems and natural sugar alternatives.', '#future-ideas', 4, 1, '2026-10-08 15:34:35'),
(5, 'MORE INCLUSIVE CHOCOLATE', 'Direct farmer compensation models and community-driven chocolate craft.', '#future-ideas', 5, 1, '2026-10-08 15:34:35');
INSERT INTO `lab_ingredient_categories` (`id`, `title`, `slug`, `image_path`, `description`, `link_url`, `sort_order`, `is_active`, `created_at`, `key_varietals`, `science_behavior`, `applications`, `lab_notes`, `full_content`) VALUES
(1, 'INDIAN FRUITS', 'indian-fruits', 'assets/images/lab-ing-fruits.jpg', 'Exploring sub-tropical Indian fruits — Alphonso mango, sun-dried Kokum, wild Amla, and pink guava — to craft vibrant acidic balances with deep single-origin cacao.', '', 2, 1, '2026-10-08 15:34:34', 'Ratnagiri Alphonso Mango, Sindhudurg Sun-Dried Kokum, Himalayan Wild Amla, Nagpur Mandarin Orange, Dehydrated Allahabad Pink Guava', 'Water Activity (aw < 0.3) is strictly controlled via low-temperature vacuum dehydration to prevent moisture migration into cocoa butter and prevent sugar bloom. Native malic and citric fruit acids are calibrated to complement cocoa polyphenols rather than overpower them.', 'Direct melanger infusions for vibrant fruit-noted bars, crisp vacuum-dried fruit inclusions in 70% dark chocolates, and micro-ground tart dusting powders.', 'Batch #089 confirmed that vacuum-dehydrated Kokum preserves its deep ruby anthocyanin pigments and sharp fruit snap without disrupting cocoa butter polymorphic Form V crystal tempering.', NULL),
(2, 'NUTS & SEEDS', 'nuts-seeds', 'assets/images/lab-ing-nuts.jpg', 'Harnessing heritage Indian nuts and nutrient-dense seeds for velvety gianduja textures, nutty aromatic complexity, and dairy-free creaminess.', '#category-nuts', 2, 1, '2026-10-08 15:34:35', 'Slow-Roasted Malabar Cashews, Mamra Almonds (Kashmir), Charoli / Chironji Seeds, Roasted Watermelon Seeds (Magaz), Giri Walnuts', 'High free oil content in nuts can trigger fat bloom if eutectic mixtures form with cocoa butter. We employ progressive convection roasting at 135°C to stabilize free fatty acids, followed by multi-stage stone grinding to < 18 microns for silky mouthfeel.', 'Single-estate stone-ground Giandujas, crunchy caramelized nut inclusions, smooth plant-based nut milk chocolates, and hand-cut praline fillings.', 'Melanger conching for 32 hours with Mamra almonds yields a velvety emulsion without requiring added emulsifiers or hydrogenated vegetable fats.', NULL),
(3, 'ALTERNATIVE SUGARS', 'alternative-sugars', 'assets/images/lab-ing-sugars.jpg', 'Replacing refined white cane sugar with unrefined native Indian jaggeries, palm nectars, and dry fruits to enhance mineral richness and nuanced molasses notes.', '#category-sugars', 3, 1, '2026-10-08 15:34:35', 'Organic Khandsari Raw Sugar, Palmyra Palm Jaggery (Karupatti), Coconut Blossom Nectar, Sun-Dried Dates Powder, Himalayan Wild Forest Honey', 'Unrefined sugars are inherently hygroscopic with trace moisture (1.2–3.5%). Pre-drying in dehumidified chambers and precision micronization are mandatory to avoid gummy viscosity spikes in the melanger.', 'Clean-label 65% & 72% dark chocolate slabs, low-glycemic artisan bars, and aromatic date-powdered cacao drinks.', 'Palmyra palm jaggery introduces warm smoky caramel notes that naturally amplify the earthy, woody terroir of Idukki and Pollachi cacao beans.', NULL),
(4, 'DAIRY & PLANT-BASED', 'dairy-plant-based', 'assets/images/lab-ing-plant.jpg', 'Pioneering indigenous A2 Vedic dairy alongside innovative vegan plant-based emulsions for ethical, rich, and thermally resilient chocolate formulations.', '#category-dairy', 4, 1, '2026-10-08 15:34:35', 'A2 Gir Cow Milk Solids, Cold-Pressed Coconut Cream Powder, Hydrolyzed Sprouted Oat Flour, Roasted Sesame Seed Pastes (Tahini)', 'Dairy proteins (casein) bind with cacao tannins to soften astringency. For vegan formulations, sprouted oat and coconut solids are engineered to mimic dairy fat melting profiles (34°C palate melt) without off-flavors.', '45% A2 Vedic Milk Chocolate, dairy-free Coconut Meltaway bars, vegan caramel ganaches, and blonde caramelized chocolate.', 'A2 beta-casein proteins demonstrate superior thermal stability during conching, preventing premature protein denaturing up to 55°C.', NULL),
(5, 'BOTANICALS & SPICES', 'botanicals-spices', 'assets/images/lab-ing-spices.jpg', 'Revitalizing ancient Indian spice routes — using fresh Western Ghats spices and medicinal botanicals to elevate chocolate into a multi-layered sensory journey.', '#category-spices', 5, 1, '2026-10-08 15:34:35', 'Tellicherry Extra Bold Black Pepper, Idukki Green Cardamom, Kerala Mace & Nutmeg, Wild Star Anise, Kashmiri Mongra Saffron', 'Volatile essential oils (piperine, cineole, safranal) are easily lost if added during high-heat conching. We deploy late-stage cocoa butter maceration at 42°C to lock in aromatic terpenes directly into the lipid crystal matrix.', 'Single-origin spiced tasting squares, warm winter seasonal bars, aromatic ganache bonbons, and savory-sweet pairings.', 'Cold-steeping crushed Tellicherry black pepper in deodorized cacao butter captures intense citrus-pine aromas while eliminating harsh throat burn.', NULL),
(7, 'Other Ingredients', 'other-ingredients', 'assets/images/placeholder.jpg', '### 01 — Ingredient Profile\r\n**A natural way to slow down fat spoilage.**\r\n\r\nRosemary extract is obtained from the rosemary herb. It contains natural antioxidant compounds that help protect fats from reacting with oxygen—a process that can cause rancid smells and unpleasant flavours over time.\r\n\r\nA plant-derived antioxidant that protects fats.\r\n\r\nRosemary extract is made from rosemary leaves and contains compounds such as carnosic acid and carnosol. These help slow the reaction between fats and oxygen, which can gradually create rancid smells and stale flavours in food.', '', 6, 1, '2026-10-26 11:28:56', '', 'Antioxidant performance without unwanted flavour.\r\n\r\nExtract selection: Antioxidant strength, colour and aroma vary with the extract\'s composition.\r\n\r\nFlavour impact: Some extracts can introduce herbal or bitter notes.\r\n\r\nFat compatibility: The extract must disperse effectively in the intended formulation.\r\n\r\nShelf-life testing: Compare treated and untreated samples under the same storage conditions to assess oxidation and sensory changes.', 'Where fat stability matters most.\r\n\r\nNut-rich chocolates: Explore protection against rancidity in almond and hazelnut ingredients.\r\n\r\nPralines and fillings: Investigate its effectiveness in fat-rich centres.\r\n\r\nChocolate spreads: Help protect oxidation-sensitive nut fats.\r\n\r\nFat-based coatings: Evaluate its potential in formulations containing oxidation-prone vegetable fats.\r\n\r\nThese are potential applications; performance must be validated in each formulation.', 'Slow oxidation. Preserve the intended flavour.\r\n\r\nRosemary extract can help protect susceptible fats from oxidation, but it is not a universal preservative. Its value lies in selecting the right extract and proving its effectiveness in the finished product.', NULL);
INSERT INTO `lab_what_if_questions` (`id`, `num_label`, `question`, `subtext`, `link_url`, `sort_order`, `is_active`, `created_at`) VALUES
(1, '01', 'Can we reduce sugar without losing melt?', NULL, '#experiments', 1, 1, '2026-10-08 15:34:34'),
(2, '02', 'Can Indian spices create a new flavour language?', NULL, '#experiments', 2, 1, '2026-10-08 15:34:34'),
(3, '03', 'Can chocolate be more regenerative?', NULL, '#experiments', 3, 1, '2026-10-08 15:34:34'),
(4, '04', 'Can fruit co-products find a place in chocolate?', NULL, '#experiments', 4, 1, '2026-10-08 15:34:34'),
(5, '05', 'Can we design a climate-resilient Indian chocolate future?', NULL, '#experiments', 5, 1, '2026-10-08 15:34:34');
INSERT INTO `media` (`id`, `filename`, `path`, `mime_type`, `size`, `uploaded_at`) VALUES
